package com.example.incidentai;
import org.springframework.stereotype.Service;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;
@Service class Orchestrator{private final SnowClient s;private final AiPlanner ai;private final IncidentRepo repo;private final MailService mail;private final ActionRegistry actions;private final ObjectMapper om;Orchestrator(SnowClient s,AiPlanner ai,IncidentRepo r,MailService m,ActionRegistry a,ObjectMapper om){this.s=s;this.ai=ai;repo=r;mail=m;actions=a;this.om=om;}@Scheduled(fixedDelayString="${app.poll-ms:60000}")void poll(){for(var i:s.get())if(!repo.existsByIncidentSysId(i.sys_id()))try{var p=ai.plan(i);IncidentJob j=new IncidentJob();j.incidentSysId=i.sys_id();j.number=i.number();j.subject=i.short_description();j.issue=i.description();j.planJson=p.raw();j.evidence=p.evidence();j.confidence=p.plan().confidence();j.token=UUID.randomUUID().toString();j.createdAt=Instant.now();j.status=p.plan().actionType().equals("NO_ACTION")||j.confidence<.75?"NEEDS_REVIEW":"PENDING_APPROVAL";repo.save(j);if(j.status.equals("PENDING_APPROVAL")){mail.send(j);s.note(j.incidentSysId,"AI plan created; approval requested. No action executed.");}}catch(Exception e){e.printStackTrace();}}@Transactional IncidentJob decide(String t,boolean ok,String by)throws Exception{IncidentJob j=repo.lock(t).orElseThrow();if(!j.status.equals("PENDING_APPROVAL"))throw new IllegalStateException("Link already used");j.decidedBy=by;j.decidedAt=Instant.now();if(!ok){j.status="DECLINED";s.note(j.incidentSysId,"Automation declined. No action executed.");return j;}j.status="PROCESSING";repo.flush();try{String out=actions.execute(om.readValue(j.planJson,ActionPlan.class));j.result=out;j.status="COMPLETED";j.processedAt=Instant.now();s.note(j.incidentSysId,"Approved automation completed: "+out);}catch(Exception e){j.result=e.getMessage();j.status="FAILED";s.note(j.incidentSysId,"Approved automation failed safely: "+e.getMessage());}return j;}}